// Package postgres implements the fuel log repository with the queries in
// queries.sql (generated by sqlc into sqlcgen/).
package postgres

import (
	"context"
	"time"

	"github.com/google/uuid"
	"github.com/shopspring/decimal"

	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/fuel/adapters/postgres/sqlcgen"
	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/fuel/domain"
	"github.com/AtmosferaSoltec/atm-km-api/internal/platform/tx"
)

// DB gives the ongoing transaction's connection, or the pool (tx.Runner).
type DB interface {
	DB(ctx context.Context) tx.DBTX
}

// Repository implements app.Repository.
type Repository struct {
	db DB
}

// NewRepository creates the repository.
func NewRepository(db DB) Repository { return Repository{db: db} }

func (r Repository) q(ctx context.Context) *sqlcgen.Queries { return sqlcgen.New(r.db.DB(ctx)) }

// Insert stores a fill-up.
func (r Repository) Insert(ctx context.Context, log domain.Log) error {
	return r.q(ctx).InsertFuelLog(ctx, sqlcgen.InsertFuelLogParams{
		ID: log.ID, UserID: log.UserID, Date: log.Date, Odometer: log.Odometer,
		FuelType: string(log.FuelType), Amount: log.Amount, IsFull: log.IsFull, CreatedAt: log.CreatedAt,
	})
}

// Delete removes a fill-up.
func (r Repository) Delete(ctx context.Context, userID, id uuid.UUID) error {
	n, err := r.q(ctx).DeleteFuelLog(ctx, sqlcgen.DeleteFuelLogParams{ID: id, UserID: userID})
	if err != nil {
		return err
	}
	if n == 0 {
		return domain.ErrNotFound
	}
	return nil
}

// List returns a page of fill-ups and how many there are.
func (r Repository) List(ctx context.Context, userID uuid.UUID, limit, offset int) ([]domain.Log, int64, error) {
	q := r.q(ctx)
	rows, err := q.ListFuelLogs(ctx, sqlcgen.ListFuelLogsParams{UserID: userID, RowLimit: int32(limit), RowOffset: int32(offset)}) //nolint:gosec // bounded by the handler
	if err != nil {
		return nil, 0, err
	}
	total, err := q.CountFuelLogs(ctx, userID)
	return toLogs(rows), total, err
}

// Since returns the fill-ups from a date on, newest first.
func (r Repository) Since(ctx context.Context, userID uuid.UUID, since time.Time) ([]domain.Log, error) {
	rows, err := r.q(ctx).FuelLogsSince(ctx, sqlcgen.FuelLogsSinceParams{UserID: userID, Date: since})
	return toLogs(rows), err
}

// HasBefore tells whether there are fill-ups before a date.
func (r Repository) HasBefore(ctx context.Context, userID uuid.UUID, before time.Time) (bool, error) {
	return r.q(ctx).HasFuelLogsBefore(ctx, sqlcgen.HasFuelLogsBeforeParams{UserID: userID, Date: before})
}

// SpentSince adds up the fill-ups from a date on.
func (r Repository) SpentSince(ctx context.Context, userID uuid.UUID, since time.Time) (decimal.Decimal, error) {
	return r.q(ctx).SpentSince(ctx, sqlcgen.SpentSinceParams{UserID: userID, Date: since})
}

// MaxOdometer is the highest reading registered.
func (r Repository) MaxOdometer(ctx context.Context, userID uuid.UUID) (decimal.Decimal, error) {
	return r.q(ctx).MaxFuelOdometer(ctx, userID)
}

// CostPerKm is the real fuel cost per km over every fill-up.
func (r Repository) CostPerKm(ctx context.Context, userID uuid.UUID) (*decimal.Decimal, error) {
	row, err := r.q(ctx).CostPerKmInputs(ctx, userID)
	if err != nil {
		return nil, err
	}
	return domain.CostPerKm(row.Logs, row.Spent, row.FirstOdometer, row.LastOdometer), nil
}

func toLogs(rows []sqlcgen.FuelLog) []domain.Log {
	logs := make([]domain.Log, len(rows))
	for i, row := range rows {
		logs[i] = domain.Log{
			ID: row.ID, UserID: row.UserID, Date: row.Date, Odometer: row.Odometer,
			FuelType: domain.FuelType(row.FuelType), Amount: row.Amount, IsFull: row.IsFull, CreatedAt: row.CreatedAt,
		}
	}
	return logs
}
